prompt --application/shared_components/plugins/template_component/amc_next_list
begin
wwv_flow_imp_shared.create_plugin(
 p_id=>wwv_flow_imp.id(365248010202807035)
,p_plugin_type=>'TEMPLATE COMPONENT'
,p_name=>'AMC_NEXT_LIST'
,p_display_name=>'Next List'
,p_supported_component_types=>'REPORT'
,p_partial_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'{case STYLE/}{when accordionRows/}<details class="amc-NList-details"><summary class="amc-NList-summary">{if ?IMAGE_URL/}<span class="amc-NList-lead amc-NList-lead--img"><img class="amc-NList-img" src="#IMAGE_URL#" width="40" height="40" alt="" loading="lazy"></span>{else/}{if ?INITIALS/}<span class="amc-NList-lead" aria-hidden="true">#INITIALS#</span>{else/}{if ?ICON/}<span class="amc-NList-lead" aria-hidden="true"><span class="fa #ICON#"></span></span>{endif/}{endif/}{endif/}',
'<span class="amc-NList-main"><span class="amc-NList-title">#TITLE#</span>{if ?SUBTITLE/}<span class="amc-NList-sub">#SUBTITLE#</span>{endif/}</span>',
'<span class="amc-NList-state{if ?STATE_LABEL/} amc-NList-state--label{endif/}">{if ?STATE_LABEL/}#STATE_LABEL#{else/}{case STATE/}{when success/}OK{when warning/}Warn{when danger/}Error{when info/}Info{otherwise/}Log{endcase/}{endif/}</span>',
'{if ?META/}<span class="amc-NList-meta">#META#</span>{endif/}<span class="amc-NList-chevron" aria-hidden="true"></span></summary>',
'<div class="amc-NList-panel">{if ?DETAILS/}<p class="amc-NList-detailsText">#DETAILS#</p>{endif/}{if ?LINK_URL/}<a class="amc-NList-open" href="#LINK_URL#">Open<span class="amc-NList-sr"> #TITLE#</span></a>{endif/}</div></details>{otherwise/}{if ?IMAGE_URL/}<span class="amc-NList-lead amc-NList-lead--img"><img class="amc-NList-img" src="#IMAGE_URL#" width="40" height="40" alt="" loading="lazy"></span>{else/}{if ?INITIALS/}<span class="amc-NList-lead" aria-hidden="true">#INITIALS#</span>{else/}{if ?ICON/}<span class="amc-NList-lead" aria-hidden="true"><span class="fa #ICON#"></span></span>{endif/}{endif/}{endif/}',
'<span class="amc-NList-main"><span class="amc-NList-title">{if ?LINK_URL/}<a class="amc-NList-link" href="#LINK_URL#">#TITLE#</a>{else/}#TITLE#{endif/}</span>{if ?SUBTITLE/}<span class="amc-NList-sub">#SUBTITLE#</span>{endif/}</span>',
'<span class="amc-NList-state{if ?STATE_LABEL/} amc-NList-state--label{endif/}">{if ?STATE_LABEL/}#STATE_LABEL#{else/}{case STATE/}{when success/}OK{when warning/}Warn{when danger/}Error{when info/}Info{otherwise/}Log{endcase/}{endif/}</span>',
'{if ?META/}<span class="amc-NList-meta">#META#</span>{endif/}',
'{if ?LINK_URL/}<span class="amc-NList-go" aria-hidden="true"></span>{endif/}{endcase/}'))
,p_default_escape_mode=>'HTML'
,p_translate_this_template=>true
,p_api_version=>1
,p_report_body_template=>'<div class="amc-NList amc-NList--#STYLE#"><ul class="amc-NList-list"{case STYLE/}{when stack3d/} tabindex="0"{endcase/}>#APEX$ROWS#</ul></div>'
,p_report_row_template=>'<li class="amc-NList-item amc-NList-item--{case STATE/}{when success/}success{when warning/}warning{when danger/}danger{when info/}info{otherwise/}neutral{endcase/}{if ?LINK_URL/} amc-NList-item--link{endif/}">#APEX$PARTIAL#</li>'
,p_css_file_urls=>'#PLUGIN_FILES#amc-next-list.css'
,p_javascript_file_urls=>'#PLUGIN_FILES#amc-next-list.js'
,p_substitute_attributes=>true
,p_subscribe_plugin_settings=>true
,p_help_text=>'Each query row is one list row. Pick a Style for the whole region, then map Title (required) and the columns the style uses: Subtitle, Meta, Image URL, Initials or Icon for the lead, State and State Label, Details for the Accordion rows style, and Link URL. Format numbers and dates in SQL. Every style is complete without JavaScript; the plug-in file only adds pointer tracking and the seamless marquee loop, and does nothing when the user prefers reduced motion.'
,p_version_identifier=>'1.0.1'
,p_files_version=>2
);
wwv_flow_imp_shared.create_plugin_attribute(
 p_id=>wwv_flow_imp.id(601130758781713005)
,p_plugin_id=>wwv_flow_imp.id(365248010202807035)
,p_attribute_scope=>'COMPONENT'
,p_attribute_sequence=>1
,p_display_sequence=>10
,p_static_id=>'STYLE'
,p_prompt=>'Style'
,p_attribute_type=>'SELECT LIST'
,p_is_required=>true
,p_default_value=>'animatedFeed'
,p_escape_mode=>'ATTR'
,p_is_translatable=>false
,p_lov_type=>'STATIC'
,p_help_text=>'Design of the list; the direction is given in brackets as motion, depth, bold or smart. animatedFeed [motion]: notification cards drop in one after another, newest marked live. marqueeLogos [motion]: customers or partners as an endless logo marquee that pauses on hover or focus and wraps when motion is reduced. spotlightRows [motion]: a light spot follows the pointer over the rows and lights their borders. stack3d [depth]: rows form a perspective stack that fans out on hover or focus; always open on touch screens. liftRows [depth]: rows are raised slabs that lift and tilt toward the pointer. neoBrutal [bold]: ink borders, hard offset shadows and flat state fills. clay [bold]: soft pillowy rows with clay icon blobs. terminal [bold]: a console log with time, level and a blinking cursor. accordionRows [smart]: each row opens to show Details; other rows dim while one is open. scrollReveal [smart]: numbered rows reveal as they scroll into view and switch to two columns in wide regions.'
);
